use std::{cell::{Cell,RefCell},rc::Rc};
use xterm_core::task_queue::{CallbackKind,Scheduler,TaskQueue,WeakTaskQueue};
struct Host { clock:Rc<Cell<f64>>, queue:Rc<RefCell<Option<WeakTaskQueue<Host>>>> }
impl Scheduler for Host {
 type Handle=u32; type Error=std::convert::Infallible;
 fn request(&mut self,_:CallbackKind)->Result<u32,Self::Error>{Ok(1)}
 fn cancel(&mut self,_:u32){}
 fn now(&self)->f64{self.clock.get()}
 fn deadline_exceeded(&mut self,_:f64){
  let queue=self.queue.borrow().as_ref().unwrap().upgrade().unwrap();
  queue.clear(); queue.enqueue(|_|false).unwrap();
 }
}
fn main(){
 let clock=Rc::new(Cell::new(0.0)); let holder=Rc::new(RefCell::new(None));
 let queue=TaskQueue::idle(Host{clock:clock.clone(),queue:holder.clone()},true);
 *holder.borrow_mut()=Some(queue.downgrade());
 queue.enqueue(move |_|{clock.set(50.0);false}).unwrap();
 queue.process(||1.0).unwrap();
 assert_eq!(queue.remaining_tasks(),1);
 println!("warning logger safely enqueued replacement");
}

