import {readFileSync,writeFileSync} from 'node:fs';
import {stripTypeScriptTypes} from 'node:module';
import vm from 'node:vm';
import assert from 'node:assert/strict';
const source=readFileSync('source_repo/src/common/TaskQueue.ts','utf8');
let clock=0; const callbacks=[]; const events=[];
const context=vm.createContext({performance:{now:()=>clock},requestIdleCallback:callback=>{callbacks.push(callback);events.push('request:'+callbacks.length);return callbacks.length;},cancelIdleCallback:id=>events.push('cancel:'+id)});
vm.runInContext(stripTypeScriptTypes(source.replace(/^import .*;\r?$/gm,'').replace(/^export /gm,''),{mode:'transform'})+'\nglobalThis.Queue=IdleTaskQueue;',context);
let queue; const logger={warn:message=>{events.push(message);queue.clear();queue.enqueue(()=>false);}};
queue=new context.Queue(logger); queue.enqueue(()=>{clock=50;return false;});
callbacks[0]({timeRemaining:()=>1});
assert.equal(queue._tasks.length,1);assert.equal(queue._i,0);assert.equal(queue._idleCallback,2);
const report={source:'source_repo/src/common/TaskQueue.ts',node:process.version,events,remaining:queue._tasks.length,index:queue._i,pending:queue._idleCallback,passed:true};
writeFileSync('results/task-platform/chloe-warning-js.json',JSON.stringify(report,null,2)+'\n');console.log(report);
